-- runtime_history_availability_before_memo(uuid[])
CREATE OR REPLACE FUNCTION public.runtime_history_availability_before_memo(p_execution_ids uuid[])
 RETURNS TABLE(execution_id uuid, available boolean)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE nodes uuid[];checks jsonb:='{}';entry record;allowed boolean;
BEGIN
 -- Statement-local sharing only. Existing permission functions remain authoritative.
 -- Expand the union of ancestors once, including through missing-run nodes just as
 -- runtime_billing_allowed's recursive CTE does before its final inner joins.
 WITH RECURSIVE reachable(id) AS (
  SELECT e.id FROM runtime_executions e
  WHERE e.id=ANY(p_execution_ids) AND e.unavailable_reason IS NULL
  UNION SELECT d.dependency_id FROM runtime_history_dependencies d JOIN reachable r ON d.execution_id=r.id
 ) SELECT coalesce(array_agg(id),ARRAY[]::uuid[]) INTO nodes FROM reachable;
 FOR entry IN
  SELECT e.id,e.actor_id,e.unavailable_reason,e.payload,r.id run_id,r.payload billing_payload
  FROM runtime_executions e JOIN bill2_runs r ON r.id=e.billing_run_id
  WHERE e.id=ANY(nodes) ORDER BY e.id
 LOOP
  allowed:=false;
  IF entry.unavailable_reason IS NULL THEN
   BEGIN
    PERFORM runtime_direct_billing_allowed(entry.actor_id,entry.billing_payload,entry.run_id);
    -- The direct check already validates billing input context. If the two frozen
    -- payloads differ, retain the independent execution-context check as well.
    IF entry.payload IS DISTINCT FROM entry.billing_payload->'input' THEN
     PERFORM runtime_context_allowed(entry.actor_id,entry.payload);
    END IF;
    allowed:=true;
   EXCEPTION WHEN raise_exception OR insufficient_privilege THEN allowed:=false;
   END;
  END IF;
  checks:=checks||jsonb_build_object(entry.id::text,allowed);
 END LOOP;
 -- A denial propagates backwards over the SAME dependency graph. Per-root actor
 -- identity is checked even for malformed cross-actor edges. UNION also terminates
 -- cycles; missing descendant runs remain ignored by the original inner-join rule.
 RETURN QUERY
 WITH RECURSIVE actors AS (
  SELECT DISTINCT e.actor_id FROM runtime_executions e WHERE e.id=ANY(p_execution_ids)
 ), denied(actor_id,id) AS (
  SELECT a.actor_id,e.id FROM actors a CROSS JOIN runtime_executions e JOIN bill2_runs r ON r.id=e.billing_run_id
  WHERE e.id=ANY(nodes) AND (e.actor_id<>a.actor_id OR NOT coalesce((checks->>e.id::text)::boolean,false))
  UNION
  SELECT denied.actor_id,d.execution_id FROM runtime_history_dependencies d JOIN denied ON d.dependency_id=denied.id
  WHERE d.execution_id=ANY(nodes)
 )
 SELECT requested.id,e.id IS NOT NULL AND r.id IS NOT NULL AND e.unavailable_reason IS NULL
  AND coalesce((checks->>e.id::text)::boolean,false)
  AND NOT EXISTS(SELECT 1 FROM denied WHERE denied.actor_id=e.actor_id AND denied.id=e.id)
 FROM (SELECT DISTINCT unnest(p_execution_ids) id) requested
 LEFT JOIN runtime_executions e ON e.id=requested.id LEFT JOIN bill2_runs r ON r.id=e.billing_run_id;
END;
$function$;
